package com.example.todo.exception; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.*; @RestControllerAdvice public class GlobalExceptionHandler {@ExceptionHandler(TodoNotFoundException.class) ResponseEntity<?> notFound(TodoNotFoundException e){return ResponseEntity.status(404).body(Map.of("status",404,"message",e.getMessage()));}@ExceptionHandler(IllegalArgumentException.class) ResponseEntity<?> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("status",400,"message",e.getMessage()));}@ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> validation(MethodArgumentNotValidException e){Map<String,String> m=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->m.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(Map.of("status",400,"message","Validation failed","errors",m));}}
